export const EMBEDDED_COMPANION_PHP_TEMPLATE: string = "<?php\n/**\n * ============================================================================\n * Bentian ERP Bridge — Conector Web Universal (HTTPS Bridge v1.1.0)\n * ============================================================================\n * Puerto: 443 (HTTPS Seguro)\n * Protocolo: HMAC-SHA256 / Bearer Token\n * Requisitos: PHP 7.4 o superior, PDO MariaDB / MySQL\n * Ubicación en Plesk: httpdocs/erp-bridge-endpoint.php\n * ============================================================================\n */\n\n// Desactivar salida de errores HTML para garantizar JSON estricto\nerror_reporting(0);\nini_set('display_errors', '0');\n\nheader('Content-Type: application/json; charset=utf-8');\nheader('X-Content-Type-Options: nosniff');\nheader('X-Frame-Options: DENY');\nheader('Access-Control-Allow-Origin: *');\nheader('Access-Control-Allow-Methods: GET, POST, OPTIONS');\nheader('Access-Control-Allow-Headers: Content-Type, Authorization, X-Bridge-Key, X-Bentian-Signature, X-Bentian-Timestamp, X-Bentian-Agent-Version, Idempotency-Key, X-File-Path, X-Product-SKU');\n\nif ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') {\n    http_response_code(204);\n    exit;\n}\n\n// ============================================================================\n// ⚠️ ATENCIÓN: CONFIGURACIÓN PARA EL PROGRAMADOR WEB / ADMINISTRADOR DE HOSTING\n// ============================================================================\n// SOLO TIENES QUE RELLENAR ESTAS 4 LÍNEAS CON LOS DATOS DE TU BASE DE DATOS:\n// (La clave secreta EB_SECRET_KEY ya viene configurada por Bentian ERP Bridge)\n// ============================================================================\n\ndefine('EB_SECRET_KEY', getenv('EB_SECRET_KEY') ?: '%%EB_SECRET_KEY%%');\ndefine('EB_DB_HOST',    getenv('EB_DB_HOST')    ?: '%%EB_DB_HOST%%');   // Habitualmente 'localhost' o '127.0.0.1'\ndefine('EB_DB_NAME',    getenv('EB_DB_NAME')    ?: '%%EB_DB_NAME%%');   // Nombre de la base de datos de tu tienda web\ndefine('EB_DB_USER',    getenv('EB_DB_USER')    ?: '%%EB_DB_USER%%');   // Usuario con permisos en MySQL / MariaDB\ndefine('EB_DB_PASS',    getenv('EB_DB_PASS')    ?: '%%EB_DB_PASS%%');   // Contraseña de MySQL / MariaDB\n\n// ============================================================================\n// 🛑 NO MODIFICAR NADA POR DEBAJO DE ESTA LÍNEA\n// El resto del archivo es el motor automático de sincronización con Factusol.\n// Al ejecutarse por primera vez, el archivo creará automáticamente las tablas\n// necesarias (eb_products, eb_stock, eb_orders) de forma 100% idempotente y segura.\n// ============================================================================\n\n// ----------------------------------------------------------------------------\n// 2. CONEXIÓN PDO A MARIADB / MYSQL LOCAL\n// ----------------------------------------------------------------------------\nfunction getDbConnection(&$errorMsg = null) {\n    static $pdo = null;\n    if ($pdo !== null) return $pdo;\n\n    if (empty(EB_DB_NAME)) {\n        $errorMsg = 'Nombre de base de datos no configurado (EB_DB_NAME está vacío)';\n        return null;\n    }\n\n    $hosts = [EB_DB_HOST];\n    if (EB_DB_HOST === '127.0.0.1') $hosts[] = 'localhost';\n    else if (EB_DB_HOST === 'localhost') $hosts[] = '127.0.0.1';\n\n    $lastException = null;\n    foreach ($hosts as $h) {\n        try {\n            $dsn = \"mysql:host=\" . $h . \";dbname=\" . EB_DB_NAME . \";charset=utf8mb4\";\n            $options = [\n                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,\n                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,\n                PDO::ATTR_EMULATE_PREPARES => false,\n            ];\n            $pdo = new PDO($dsn, EB_DB_USER, EB_DB_PASS, $options);\n            return $pdo;\n        } catch (Exception $e) {\n            $lastException = $e;\n        }\n    }\n\n    $errorMsg = $lastException ? $lastException->getMessage() : 'Error desconocido al conectar con MariaDB/MySQL';\n    return null;\n}\n\n// ----------------------------------------------------------------------------\n// 3. AUTO-INSTALACIÓN DE TABLAS CANÓNICAS (IDEMPOTENTE - NUNCA BORRA DATOS)\n// ----------------------------------------------------------------------------\nfunction ensureTablesExist($pdo) {\n    if (!$pdo) return false;\n    try {\n        $pdo->exec(\"\n            CREATE TABLE IF NOT EXISTS `eb_products` (\n              `code` VARCHAR(50) NOT NULL PRIMARY KEY,\n              `sku` VARCHAR(50) DEFAULT NULL,\n              `name` VARCHAR(255) NOT NULL,\n              `description` TEXT DEFAULT NULL,\n              `section_code` VARCHAR(10) DEFAULT NULL,\n              `section_name` VARCHAR(100) DEFAULT NULL,\n              `family_code` VARCHAR(10) DEFAULT NULL,\n              `family_name` VARCHAR(100) DEFAULT NULL,\n              `price` DECIMAL(12, 4) NOT NULL DEFAULT 0.0000,\n              `sale_price` DECIMAL(12, 4) DEFAULT NULL,\n              `vat_rate` DECIMAL(5, 2) NOT NULL DEFAULT 21.00,\n              `price_with_vat` DECIMAL(12, 4) NOT NULL DEFAULT 0.0000,\n              `sale_price_with_vat` DECIMAL(12, 4) DEFAULT NULL,\n              `unit_of_measure` VARCHAR(20) DEFAULT 'UNIDADES',\n              `weight` DECIMAL(10, 3) DEFAULT 0.000,\n              `barcode` VARCHAR(50) DEFAULT NULL,\n              `imgart` VARCHAR(255) DEFAULT NULL,\n              `image_url` VARCHAR(500) DEFAULT NULL,\n              `active` TINYINT(1) NOT NULL DEFAULT 1,\n              `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n              INDEX `idx_family` (`family_code`),\n              INDEX `idx_active` (`active`)\n            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n            CREATE TABLE IF NOT EXISTS `eb_stock` (\n              `code` VARCHAR(50) NOT NULL PRIMARY KEY,\n              `stock` DECIMAL(12, 3) NOT NULL DEFAULT 0.000,\n              `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n              INDEX `idx_stock_val` (`stock`)\n            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n            CREATE TABLE IF NOT EXISTS `eb_orders` (\n              `id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY,\n              `order_number` VARCHAR(50) NOT NULL UNIQUE,\n              `status` ENUM('PENDING', 'SYNCED', 'CANCELLED') NOT NULL DEFAULT 'PENDING',\n              `customer_data` LONGTEXT NOT NULL,\n              `order_lines` LONGTEXT NOT NULL,\n              `payment_method` VARCHAR(50) NOT NULL,\n              `payment_status` VARCHAR(50) NOT NULL,\n              `payment_reference` VARCHAR(100) DEFAULT NULL,\n              `subtotal` DECIMAL(12, 2) NOT NULL,\n              `tax_total` DECIMAL(12, 2) NOT NULL,\n              `shipping_cost` DECIMAL(12, 2) NOT NULL DEFAULT 0.00,\n              `total` DECIMAL(12, 2) NOT NULL,\n              `factusol_order_number` INT DEFAULT NULL,\n              `factusol_series` VARCHAR(5) DEFAULT NULL,\n              `factusol_unstocked` TINYINT(1) NOT NULL DEFAULT 0,\n              `unstocked_at` TIMESTAMP NULL DEFAULT NULL,\n              `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n              `synced_at` TIMESTAMP NULL DEFAULT NULL,\n              INDEX `idx_status` (`status`),\n              INDEX `idx_unstocked` (`status`, `factusol_unstocked`),\n              INDEX `idx_created` (`created_at`)\n            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n        \");\n        try {\n            $pdo->exec(\"ALTER TABLE `eb_products` ADD COLUMN IF NOT EXISTS `sale_price` DECIMAL(12, 4) DEFAULT NULL\");\n            $pdo->exec(\"ALTER TABLE `eb_products` ADD COLUMN IF NOT EXISTS `sale_price_with_vat` DECIMAL(12, 4) DEFAULT NULL\");\n            $pdo->exec(\"ALTER TABLE `eb_products` ADD COLUMN IF NOT EXISTS `imgart` VARCHAR(255) DEFAULT NULL\");\n            $pdo->exec(\"ALTER TABLE `eb_products` ADD COLUMN IF NOT EXISTS `image_url` VARCHAR(500) DEFAULT NULL\");\n        } catch (Exception $colErr) {}\n        try {\n            $pdo->exec(\"ALTER TABLE `eb_orders` ADD COLUMN IF NOT EXISTS `factusol_unstocked` TINYINT(1) NOT NULL DEFAULT 0\");\n            $pdo->exec(\"ALTER TABLE `eb_orders` ADD COLUMN IF NOT EXISTS `unstocked_at` TIMESTAMP NULL DEFAULT NULL\");\n        } catch (Exception $orderColErr) {\n            try {\n                $cols = $pdo->query(\"SHOW COLUMNS FROM `eb_orders` LIKE 'factusol_unstocked'\")->fetchAll();\n                if (empty($cols)) {\n                    $pdo->exec(\"ALTER TABLE `eb_orders` ADD COLUMN `factusol_unstocked` TINYINT(1) NOT NULL DEFAULT 0\");\n                }\n            } catch (Exception $e1) {}\n            try {\n                $cols = $pdo->query(\"SHOW COLUMNS FROM `eb_orders` LIKE 'unstocked_at'\")->fetchAll();\n                if (empty($cols)) {\n                    $pdo->exec(\"ALTER TABLE `eb_orders` ADD COLUMN `unstocked_at` TIMESTAMP NULL DEFAULT NULL\");\n                }\n            } catch (Exception $e2) {}\n        }\n        return true;\n    } catch (Exception $e) {\n        return false;\n    }\n}\n\n// ----------------------------------------------------------------------------\n// 4. DIRECTORIO BASE PARA IMÁGENES PÚBLICAS\n// ----------------------------------------------------------------------------\nfunction getPublicImagesBaseDir() {\n    $candidates = [\n        __DIR__ . '/assets/img/factusolImg',\n        __DIR__ . '/tienda/assets/img/factusolImg',\n        dirname(__DIR__) . '/tienda/assets/img/factusolImg',\n        __DIR__ . '/uploads/products',\n    ];\n    foreach ($candidates as $cand) {\n        if (is_dir($cand)) {\n            return $cand;\n        }\n    }\n    $defaultDir = __DIR__ . '/assets/img/factusolImg';\n    if (!is_dir($defaultDir)) {\n        @mkdir($defaultDir, 0755, true);\n    }\n    return $defaultDir;\n}\n\n// ----------------------------------------------------------------------------\n// 5. AUTENTICACIÓN Y SEGURIDAD HMAC-SHA256 / BEARER / X-BRIDGE-KEY\n// ----------------------------------------------------------------------------\nfunction verifyAuthentication() {\n    $secret = EB_SECRET_KEY;\n    if (empty($secret) || strpos($secret, '%%EB_SECRET_KEY%%') !== false || strlen($secret) < 16) {\n        http_response_code(503);\n        echo json_encode(['error' => 'Endpoint no configurado: Clave secreta no establecida o insegura (EB_SECRET_KEY debe configurarse con al menos 16 caracteres)']);\n        exit;\n    }\n\n    $headers = function_exists('getallheaders') ? getallheaders() : [];\n    $authHeader = isset($headers['Authorization']) ? $headers['Authorization'] : (isset($_SERVER['HTTP_AUTHORIZATION']) ? $_SERVER['HTTP_AUTHORIZATION'] : '');\n    $bridgeKeyHeader = isset($headers['X-Bridge-Key']) ? $headers['X-Bridge-Key'] : (isset($headers['x-bridge-key']) ? $headers['x-bridge-key'] : (isset($_SERVER['HTTP_X_BRIDGE_KEY']) ? $_SERVER['HTTP_X_BRIDGE_KEY'] : ''));\n    $signature = isset($headers['X-Bentian-Signature']) ? $headers['X-Bentian-Signature'] : (isset($_SERVER['HTTP_X_BENTIAN_SIGNATURE']) ? $_SERVER['HTTP_X_BENTIAN_SIGNATURE'] : '');\n    $timestamp = isset($headers['X-Bentian-Timestamp']) ? intval($headers['X-Bentian-Timestamp']) : (isset($_SERVER['HTTP_X_BENTIAN_TIMESTAMP']) ? intval($_SERVER['HTTP_X_BENTIAN_TIMESTAMP']) : 0);\n\n    // 1. Bearer Token\n    if ($authHeader && preg_match('/Bearer\\s+(.*)$/i', $authHeader, $matches)) {\n        if (hash_equals($secret, trim($matches[1]))) {\n            return true;\n        }\n    }\n\n    // 2. Cabecera X-Bridge-Key (alternativa sin prefijo Bearer)\n    if ($bridgeKeyHeader && hash_equals($secret, trim($bridgeKeyHeader))) {\n        return true;\n    }\n\n    // 3. Firma HMAC-SHA256\n    if ($signature && $timestamp > 0) {\n        if (abs(time() - $timestamp) > 300) {\n            http_response_code(401);\n            echo json_encode(['error' => 'Timestamp expirado (desfase superior a 5 minutos)']);\n            exit;\n        }\n        $rawPayload = file_get_contents('php://input');\n        $expectedSignature = hash_hmac('sha256', $timestamp . $rawPayload, $secret);\n        if (hash_equals($expectedSignature, $signature)) {\n            return true;\n        }\n    }\n\n    http_response_code(401);\n    echo json_encode(['error' => 'Firma o token de autorización no válido. Se requiere cabecera Authorization: Bearer <secret> o X-Bridge-Key: <secret>']);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// 6. ENRUTADOR DE ACCIONES (Compatible con Query Params y PATH_INFO de Angular)\n// ----------------------------------------------------------------------------\n$requestUri = $_SERVER['REQUEST_URI'] ?? '';\n$pathInfo = $_SERVER['PATH_INFO'] ?? '';\n$uriPath = parse_url($requestUri, PHP_URL_PATH) ?? '';\n\n$route = '';\nif (!empty($_GET['action'])) {\n    $route = trim($_GET['action']);\n} else if (!empty($pathInfo)) {\n    $route = trim($pathInfo, '/');\n} else if (preg_match('#/erp-bridge-endpoint\\.php(?:/([^?]+))?#i', $uriPath, $m)) {\n    $route = isset($m[1]) ? trim($m[1], '/') : '';\n}\n\n$routeParts = explode('/', $route);\n$mainAction = strtolower($routeParts[0] ?? '');\n$routeParam = $routeParts[1] ?? '';\n\nif (empty($mainAction)) {\n    $mainAction = ($_SERVER['REQUEST_METHOD'] === 'POST') ? 'create_order' : 'ping';\n}\n\n// ----------------------------------------------------------------------------\n// RUTA PÚBLICA: PING / HEALTH\n// ----------------------------------------------------------------------------\nif ($mainAction === 'ping' || $mainAction === 'health') {\n    $dbErr = null;\n    $pdo = getDbConnection($dbErr);\n    $tablesOk = false;\n    $articleCount = 0;\n    if ($pdo) {\n        $tablesOk = ensureTablesExist($pdo);\n        try {\n            $stmt = $pdo->query(\"SELECT COUNT(*) FROM eb_products\");\n            $articleCount = (int)$stmt->fetchColumn();\n        } catch (Exception $e) {}\n    }\n\n    $baseImgDir = getPublicImagesBaseDir();\n\n    echo json_encode([\n        'status' => 'ok',\n        'success' => true,\n        'service' => 'Bentian ERP Bridge Universal Web Connector',\n        'version' => '1.1.0',\n        'latestAgentVersion' => '0.2.6',\n        'phpVersion' => PHP_VERSION,\n        'databaseConnected' => ($pdo !== null),\n        'tablesReady' => $tablesOk,\n        'articleCount' => $articleCount,\n        'imagesSupported' => true,\n        'imagesDirectory' => basename($baseImgDir),\n        'database' => [\n            'connected' => ($pdo !== null),\n            'tablesReady' => $tablesOk,\n            'articleCount' => $articleCount,\n            'database' => EB_DB_NAME,\n            'error' => $dbErr,\n        ],\n        'error' => $dbErr,\n        'timestamp' => time(),\n        'https' => (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (isset($_SERVER['SERVER_PORT']) && $_SERVER['SERVER_PORT'] == 443),\n    ]);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// RUTA PÚBLICA: AUTO-UPDATE MANIFEST PROXY / FALLBACK\n// ----------------------------------------------------------------------------\nif ($mainAction === 'check_update' || $mainAction === 'update_manifest') {\n    $remoteManifestUrl = 'https://bridge.cristianjm.com/releases/latest.json';\n    $ctx = stream_context_create([\n        'http' => [\n            'timeout' => 5,\n            'user_agent' => 'Bentian-Universal-Bridge/1.1.0',\n        ],\n        'ssl' => [\n            'verify_peer' => true,\n            'verify_peer_name' => true,\n        ]\n    ]);\n    $content = @file_get_contents($remoteManifestUrl, false, $ctx);\n    if ($content !== false && !empty($content)) {\n        echo $content;\n    } else {\n        echo json_encode([\n            'latestVersion' => '0.2.6',\n            'publishedAt' => '2026-09-18T16:57:52.351Z',\n            'stable' => [\n                'version' => '0.2.6',\n                'channel' => 'stable',\n                'platform' => 'win32_x64',\n                'downloadUrl' => 'https://bridge.cristianjm.com/releases/v0.2.6/BentianAgent.exe',\n                'sha256' => '46ddeaf2a78c7c0723dae00707197c96beaa988b390b34a22c4da58397c2c8d2',\n                'signature' => '4Dpouas2UntXny6lqfEVsQwSvG5rb/0t1l/PWQVZT13AVmhlnjdi82X4Wz65Az8vIO7xv/uoyIp8Bt9EpTA/BA==',\n                'fileSize' => 91718656,\n                'releaseNotes' => 'Lanzamiento oficial Bentian Agent v0.2.6 - Sincronización Factusol & WooCommerce',\n                'mandatory' => false,\n                'minVersion' => '0.1.0',\n            ]\n        ]);\n    }\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// RUTA PÚBLICA: TARIFAS (Compatible con RatesService de Angular)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'rates') {\n    echo json_encode([\n        [\n            'codtar' => 'INTERNET',\n            'destar' => 'INTERNET',\n            'martar' => '0',\n            'ivatar' => '21',\n            'diitar' => '0',\n        ]\n    ]);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// RUTA PÚBLICA: SECCIONES (Compatible con SectionService de Angular)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'secction' || $mainAction === 'sections') {\n    $pdo = getDbConnection();\n    if (!$pdo) {\n        echo json_encode([]);\n        exit;\n    }\n    ensureTablesExist($pdo);\n    $stmt = $pdo->query(\"\n        SELECT DISTINCT \n            section_code AS codsec, \n            COALESCE(section_name, section_code) AS dessec \n        FROM eb_products \n        WHERE section_code IS NOT NULL AND section_code != '' \n        ORDER BY section_code ASC\n    \");\n    $sections = $stmt->fetchAll();\n    echo json_encode($sections);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// RUTA PÚBLICA: FAMILIAS Y ARTÍCULOS POR FAMILIA (Compatible con FamilyService)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'family' || $mainAction === 'families') {\n    $pdo = getDbConnection();\n    if (!$pdo) {\n        echo json_encode([]);\n        exit;\n    }\n    ensureTablesExist($pdo);\n\n    $famId = !empty($routeParam) ? trim($routeParam) : (isset($_GET['id']) ? trim($_GET['id']) : (isset($_GET['famId']) ? trim($_GET['famId']) : ''));\n\n    if (!empty($famId)) {\n        // Artículos de una familia específica\n        $stmt = $pdo->prepare(\"\n            SELECT \n                p.code AS codart,\n                p.name AS desart,\n                p.description AS dewart,\n                p.price AS pcoart,\n                p.sale_price AS sale_price,\n                p.price_with_vat AS pvp,\n                p.sale_price_with_vat AS sale_pvp,\n                p.family_code AS famart,\n                p.barcode AS eanart,\n                p.unit_of_measure AS measure,\n                p.vat_rate AS tivart,\n                IF(p.imgart IS NOT NULL AND p.imgart != '', \n                   IF(p.imgart LIKE '/%', p.imgart, CONCAT('/', p.imgart)), \n                   '') AS imgart,\n                p.image_url AS image_url,\n                COALESCE(s.stock, 0) AS stock \n            FROM eb_products p \n            LEFT JOIN eb_stock s ON p.code = s.code \n            WHERE p.active = 1 AND p.family_code = :famId\n            ORDER BY p.name ASC\n        \");\n        $stmt->execute([':famId' => $famId]);\n        echo json_encode($stmt->fetchAll());\n        exit;\n    } else {\n        // Listado de familias\n        $stmt = $pdo->query(\"\n            SELECT DISTINCT \n                family_code AS codfam, \n                COALESCE(family_name, family_code) AS desfam \n            FROM eb_products \n            WHERE family_code IS NOT NULL AND family_code != '' \n            ORDER BY family_code ASC\n        \");\n        echo json_encode($stmt->fetchAll());\n        exit;\n    }\n}\n\n// ----------------------------------------------------------------------------\n// RUTA PÚBLICA: CATÁLOGO COMPLETO Y MEDIDAS (Compatible con DataService)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'catalog' || $mainAction === 'articles') {\n    $pdo = getDbConnection();\n    if (!$pdo) {\n        http_response_code(503);\n        echo json_encode(['error' => 'Base de datos no disponible']);\n        exit;\n    }\n    ensureTablesExist($pdo);\n\n    // Búsqueda opcional\n    $searchQuery = isset($_GET['query']) ? trim($_GET['query']) : '';\n    $where = \"WHERE p.active = 1\";\n    $params = [];\n    if (!empty($searchQuery)) {\n        $where .= \" AND (p.name LIKE :q1 OR p.code LIKE :q2 OR p.barcode LIKE :q3 OR p.description LIKE :q4)\";\n        $searchTerm = '%' . $searchQuery . '%';\n        $params[':q1'] = $searchTerm;\n        $params[':q2'] = $searchTerm;\n        $params[':q3'] = $searchTerm;\n        $params[':q4'] = $searchTerm;\n    }\n\n    $stmt = $pdo->prepare(\"\n        SELECT \n            p.code AS codart,\n            p.name AS desart,\n            p.description AS dewart,\n            p.price AS pcoart,\n            p.sale_price AS sale_price,\n            p.price_with_vat AS pvp,\n            p.sale_price_with_vat AS sale_pvp,\n            p.family_code AS famart,\n            p.barcode AS eanart,\n            p.unit_of_measure AS measure,\n            p.vat_rate AS tivart,\n            IF(p.imgart IS NOT NULL AND p.imgart != '', \n               IF(p.imgart LIKE '/%', p.imgart, CONCAT('/', p.imgart)), \n               '') AS imgart,\n            p.image_url AS image_url,\n            p.active,\n            p.section_code,\n            p.section_name,\n            p.family_name,\n            COALESCE(s.stock, 0) AS stock \n        FROM eb_products p \n        LEFT JOIN eb_stock s ON p.code = s.code \n        {$where}\n        ORDER BY p.name ASC\n    \");\n    $stmt->execute($params);\n    $items = $stmt->fetchAll();\n\n    $stmtMeasures = $pdo->query(\"SELECT DISTINCT unit_of_measure FROM eb_products WHERE unit_of_measure IS NOT NULL AND unit_of_measure != ''\");\n    $rawMeasures = $stmtMeasures->fetchAll(PDO::FETCH_COLUMN) ?: ['UNIDADES'];\n    $measures = [];\n    foreach ($rawMeasures as $m) {\n        $measures[] = ['desume' => $m];\n    }\n\n    if (!empty($searchQuery)) {\n        // En búsqueda devuelve array directo de artículos\n        echo json_encode($items);\n    } else {\n        echo json_encode(['success' => true, 'count' => count($items), 'articles' => $items, 'measures' => $measures]);\n    }\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// RUTA PÚBLICA: MEDIDAS\n// ----------------------------------------------------------------------------\nif ($mainAction === 'measures') {\n    $pdo = getDbConnection();\n    if (!$pdo) {\n        echo json_encode(['measures' => [['desume' => 'UNIDADES']]]);\n        exit;\n    }\n    ensureTablesExist($pdo);\n    $stmt = $pdo->query(\"SELECT DISTINCT unit_of_measure FROM eb_products WHERE unit_of_measure IS NOT NULL AND unit_of_measure != ''\");\n    $rawMeasures = $stmt->fetchAll(PDO::FETCH_COLUMN) ?: ['UNIDADES'];\n    $measures = [];\n    foreach ($rawMeasures as $m) {\n        $measures[] = ['desume' => $m];\n    }\n    echo json_encode(['measures' => $measures]);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// RUTA PÚBLICA: CREACIÓN DE PEDIDOS (Checkout de la tienda)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'create_order' || $mainAction === 'order') {\n    $pdo = getDbConnection();\n    if (!$pdo) {\n        http_response_code(503);\n        echo json_encode(['error' => 'Base de datos no disponible']);\n        exit;\n    }\n    ensureTablesExist($pdo);\n\n    $rawBody = file_get_contents('php://input');\n    $payload = json_decode($rawBody, true) ?: [];\n\n    $shipping = $payload['shippingData'] ?? [];\n    $orderData = $payload['order'] ?? [];\n    $lines = $orderData['lines'] ?? $orderData['lineas'] ?? $payload['lines'] ?? $payload['lineas'] ?? [];\n\n    if (!is_array($lines) || count($lines) === 0) {\n        http_response_code(400);\n        echo json_encode(['error' => 'El pedido debe contener al menos una línea de artículo']);\n        exit;\n    }\n\n    // Límite máximo de líneas de pedido para prevenir DoS en base de datos\n    if (count($lines) > 200) {\n        http_response_code(400);\n        echo json_encode(['error' => 'El pedido supera el límite máximo permitido de 200 líneas']);\n        exit;\n    }\n\n    $total = floatval($orderData['total'] ?? $orderData['cabecera']['totpcl'] ?? $payload['total'] ?? 0);\n    $subtotal = floatval($orderData['subtotal'] ?? $orderData['cabecera']['net1pcl'] ?? $payload['subtotal'] ?? $total);\n    $taxTotal = floatval($orderData['taxTotal'] ?? $orderData['cabecera']['iiva1pcl'] ?? $payload['taxTotal'] ?? 0);\n    $shippingCost = floatval($payload['shippingCost'] ?? 0);\n\n    // Validación estricta de importes numéricos positivos y razonables\n    if ($total < 0 || $subtotal < 0 || $taxTotal < 0 || $shippingCost < 0 ||\n        $total > 1000000 || $subtotal > 1000000 || $taxTotal > 500000 || $shippingCost > 10000 ||\n        !is_finite($total) || !is_finite($subtotal) || !is_finite($taxTotal) || !is_finite($shippingCost)) {\n        http_response_code(400);\n        echo json_encode(['error' => 'Importes de pedido no válidos o fuera de rango permitido']);\n        exit;\n    }\n\n    // Validación de cantidades y precios en cada línea\n    foreach ($lines as $idx => $line) {\n        if (!is_array($line)) {\n            http_response_code(400);\n            echo json_encode(['error' => \"Formato no válido en la línea {$idx} del pedido\"]);\n            exit;\n        }\n        $qty = floatval($line['canlpc'] ?? $line['quantity'] ?? $line['qty'] ?? $line['unidades'] ?? 1);\n        if ($qty <= 0 || $qty > 100000 || !is_finite($qty)) {\n            http_response_code(400);\n            echo json_encode(['error' => \"Cantidad no válida en la línea {$idx} del pedido\"]);\n            exit;\n        }\n        $linePrice = floatval($line['prelpc'] ?? $line['price'] ?? $line['precio'] ?? 0);\n        if ($linePrice < 0 || $linePrice > 1000000 || !is_finite($linePrice)) {\n            http_response_code(400);\n            echo json_encode(['error' => \"Precio no válido en la línea {$idx} del pedido\"]);\n            exit;\n        }\n    }\n\n    // No confiar ciegamente en paymentStatus: 'COMPLETED' enviado desde el cliente web.\n    // El estado inicial del pedido web debe ser PENDING_PAYMENT salvo que provenga de pasarela verificada.\n    $rawPayStatus = strtoupper(trim(strval($payload['paymentStatus'] ?? '')));\n    $payStatus = 'PENDING_PAYMENT';\n    if ($rawPayStatus === 'PENDING' || $rawPayStatus === 'PENDING_PAYMENT' || $rawPayStatus === 'ON_HOLD') {\n        $payStatus = $rawPayStatus;\n    }\n\n    $orderNumber = 'WEB-' . date('Ymd') . '-' . strtoupper(substr(uniqid(), -5));\n\n    $stmt = $pdo->prepare(\"\n        INSERT INTO `eb_orders`\n          (`order_number`, `status`, `customer_data`, `order_lines`, `payment_method`, `payment_status`, `payment_reference`, `subtotal`, `tax_total`, `shipping_cost`, `total`, `created_at`)\n        VALUES\n          (:orderNum, 'PENDING', :custData, :linesData, :payMethod, :payStatus, :payRef, :subtotal, :taxTotal, :shipCost, :total, NOW())\n    \");\n\n    $success = $stmt->execute([\n        ':orderNum' => $orderNumber,\n        ':custData' => json_encode($shipping, JSON_UNESCAPED_UNICODE),\n        ':linesData' => json_encode($lines, JSON_UNESCAPED_UNICODE),\n        ':payMethod' => substr($payload['paymentMethod'] ?? $payload['paymentMethodType'] ?? 'paypal', 0, 50),\n        ':payStatus' => substr($payStatus, 0, 50),\n        ':payRef' => substr($payload['paymentReference'] ?? $payload['paymentMethodId'] ?? '', 0, 100),\n        ':subtotal' => $subtotal,\n        ':taxTotal' => $taxTotal,\n        ':shipCost' => $shippingCost,\n        ':total' => $total,\n    ]);\n\n    $newId = $pdo->lastInsertId();\n    echo json_encode([\n        'success' => $success,\n        'pedidoId' => intval($newId),\n        'orderNumber' => $orderNumber,\n        'message' => 'Pedido registrado correctamente en espera de Factusol',\n    ]);\n    exit;\n}\n\n// ============================================================================\n// ACCIONES PROTEGIDAS DEL AGENTE LOCAL Y WEBHOOKS AUTENTICADOS (Requieren Secret Key)\n// ============================================================================\nverifyAuthentication();\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA / WEBHOOK AUTENTICADO: CANCELACIÓN DE PEDIDOS (Pasarelas / Agente)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'cancel_order' || $mainAction === 'order_cancel' || $mainAction === 'cancel' || $mainAction === 'payment_webhook' || $mainAction === 'webhook') {\n    $pdo = getDbConnection();\n    if (!$pdo) {\n        http_response_code(503);\n        echo json_encode(['error' => 'Base de datos no disponible']);\n        exit;\n    }\n    ensureTablesExist($pdo);\n\n    $rawBody = file_get_contents('php://input');\n    $payload = json_decode($rawBody, true) ?: [];\n\n    // Si es un webhook de Stripe/PayPal/Redsys, verificar si corresponde a reembolso o cancelación\n    $isWebhook = ($mainAction === 'webhook' || $mainAction === 'payment_webhook');\n    if ($isWebhook) {\n        $eventType = strtolower($payload['type'] ?? $payload['event_type'] ?? $payload['event'] ?? '');\n        $eventStatus = strtolower($payload['status'] ?? '');\n        $isCancellationEvent = (\n            strpos($eventType, 'refund') !== false ||\n            strpos($eventType, 'cancel') !== false ||\n            strpos($eventType, 'denied') !== false ||\n            in_array($eventStatus, ['cancelled', 'canceled', 'refunded', 'denied', 'failed'])\n        );\n        if (!$isCancellationEvent && empty($_GET['order_number']) && empty($payload['orderNumber'])) {\n            echo json_encode(['status' => 'ignored', 'message' => 'Evento de webhook no relacionado con cancelación o reembolso']);\n            exit;\n        }\n    }\n\n    $orderNum = trim(strval($payload['orderNumber'] ?? $payload['order_number'] ?? $payload['data']['object']['metadata']['order_number'] ?? $_GET['order_number'] ?? $_GET['orderNumber'] ?? ''));\n    $orderId = intval($payload['orderId'] ?? $payload['order_id'] ?? $payload['id'] ?? $_GET['id'] ?? $_GET['orderId'] ?? 0);\n    $payRef = trim(strval($payload['paymentReference'] ?? $payload['payment_reference'] ?? $payload['data']['object']['id'] ?? $_GET['payment_reference'] ?? ''));\n    $reason = trim(strval($payload['reason'] ?? $payload['cancel_reason'] ?? 'Cancelado por cliente o pasarela de pago'));\n\n    if (empty($orderNum) && $orderId <= 0 && empty($payRef)) {\n        http_response_code(400);\n        echo json_encode(['error' => 'Identificador de pedido no proporcionado (orderNumber, orderId o paymentReference)']);\n        exit;\n    }\n\n    $where = [];\n    $params = [];\n    if (!empty($orderNum)) {\n        $where[] = \"`order_number` = :orderNum\";\n        $params[':orderNum'] = $orderNum;\n    }\n    if ($orderId > 0) {\n        $where[] = \"`id` = :orderId\";\n        $params[':orderId'] = $orderId;\n    }\n    if (!empty($payRef)) {\n        $where[] = \"`payment_reference` = :payRef\";\n        $params[':payRef'] = $payRef;\n    }\n\n    $whereClause = implode(' OR ', $where);\n    $stmt = $pdo->prepare(\"SELECT id, order_number, status, factusol_order_number, factusol_unstocked FROM `eb_orders` WHERE {$whereClause} LIMIT 1\");\n    $stmt->execute($params);\n    $existing = $stmt->fetch();\n\n    if (!$existing) {\n        http_response_code(404);\n        echo json_encode(['error' => 'Pedido no encontrado para cancelar']);\n        exit;\n    }\n\n    $updateStmt = $pdo->prepare(\"\n        UPDATE `eb_orders` \n        SET `status` = 'CANCELLED',\n            `payment_status` = 'CANCELLED'\n        WHERE `id` = :id\n    \");\n    $updateStmt->execute([':id' => $existing['id']]);\n\n    echo json_encode([\n        'success' => true,\n        'orderId' => intval($existing['id']),\n        'orderNumber' => $existing['order_number'],\n        'status' => 'CANCELLED',\n        'hadFactusolOrder' => !empty($existing['factusol_order_number']),\n        'factusolUnstocked' => intval($existing['factusol_unstocked'] ?? 0),\n        'message' => 'Pedido cancelado correctamente en la tienda online',\n    ]);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: CHECK_IMAGES (Dirty-Checking de fotos existentes en hosting)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'check_images') {\n    $rawBody = file_get_contents('php://input');\n    $data = json_decode($rawBody, true) ?: [];\n    $imagesToCheck = isset($data['images']) && is_array($data['images']) ? $data['images'] : [];\n\n    $baseDir = getPublicImagesBaseDir();\n    $missing = [];\n    $existing = [];\n\n    foreach ($imagesToCheck as $img) {\n        $relPath = is_array($img) ? ($img['path'] ?? '') : strval($img);\n        $expectedSize = is_array($img) && isset($img['size']) ? intval($img['size']) : null;\n\n        $cleanPath = ltrim(str_replace('\\\\', '/', $relPath), '/');\n        if (empty($cleanPath) || strpos($cleanPath, '..') !== false) {\n            continue;\n        }\n\n        $fullPath = $baseDir . '/' . $cleanPath;\n        if (file_exists($fullPath) && is_file($fullPath)) {\n            if ($expectedSize !== null && $expectedSize > 0) {\n                $actualSize = filesize($fullPath);\n                if (abs($actualSize - $expectedSize) <= 10) {\n                    $existing[] = $relPath;\n                    continue;\n                }\n            } else {\n                $existing[] = $relPath;\n                continue;\n            }\n        }\n        $missing[] = $relPath;\n    }\n\n    echo json_encode([\n        'success' => true,\n        'totalChecked' => count($imagesToCheck),\n        'existingCount' => count($existing),\n        'missingCount' => count($missing),\n        'missing' => $missing,\n    ]);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: UPLOAD_IMAGE (Subida directa de fotos por HTTPS)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'upload_image') {\n    $targetRelPath = isset($_GET['path']) ? trim($_GET['path']) : '';\n    if (empty($targetRelPath) && isset($_SERVER['HTTP_X_FILE_PATH'])) {\n        $targetRelPath = trim($_SERVER['HTTP_X_FILE_PATH']);\n    }\n\n    // Saneamiento de seguridad contra Directory Traversal\n    $targetRelPath = ltrim(str_replace('\\\\', '/', $targetRelPath), '/');\n    if (empty($targetRelPath) || strpos($targetRelPath, '..') !== false) {\n        http_response_code(400);\n        echo json_encode(['error' => 'Ruta de archivo no especificada o inválida']);\n        exit;\n    }\n\n    // Validar extensión de imagen (solo formatos seguros sin SVG para prevenir XSS)\n    $ext = strtolower(pathinfo($targetRelPath, PATHINFO_EXTENSION));\n    $allowedExts = ['jpg', 'jpeg', 'png', 'webp'];\n    if (!in_array($ext, $allowedExts)) {\n        http_response_code(400);\n        echo json_encode(['error' => 'Extensión de imagen no permitida: ' . $ext . '. Solo se permiten formatos seguros (jpg, jpeg, png, webp)']);\n        exit;\n    }\n\n    $tempSource = null;\n    $rawContent = null;\n    if (isset($_FILES['image']) && is_uploaded_file($_FILES['image']['tmp_name'])) {\n        $tempSource = $_FILES['image']['tmp_name'];\n    } else if (isset($_FILES['file']) && is_uploaded_file($_FILES['file']['tmp_name'])) {\n        $tempSource = $_FILES['file']['tmp_name'];\n    } else {\n        $rawContent = file_get_contents('php://input');\n        if (empty($rawContent)) {\n            http_response_code(400);\n            echo json_encode(['error' => 'Contenido de imagen vacío']);\n            exit;\n        }\n    }\n\n    $baseDir = getPublicImagesBaseDir();\n    $targetFullPath = $baseDir . '/' . $targetRelPath;\n    $targetDir = dirname($targetFullPath);\n\n    if (!is_dir($targetDir)) {\n        @mkdir($targetDir, 0755, true);\n    }\n\n    if ($tempSource) {\n        $saved = @move_uploaded_file($tempSource, $targetFullPath);\n        if (!$saved) {\n            $saved = @copy($tempSource, $targetFullPath);\n        }\n    } else {\n        $saved = (file_put_contents($targetFullPath, $rawContent) !== false);\n    }\n\n    if (!$saved) {\n        http_response_code(500);\n        echo json_encode(['error' => 'No se pudo escribir el archivo en el servidor: ' . $targetRelPath]);\n        exit;\n    }\n\n    // Replicación secundaria automática si existe subdirectorio de tienda\n    $subdomainCandidates = [\n        __DIR__ . '/tienda/assets/img/factusolImg/' . $targetRelPath,\n    ];\n    foreach ($subdomainCandidates as $subCand) {\n        $subDir = dirname($subCand);\n        if (is_dir(dirname($subDir))) {\n            if (!is_dir($subDir)) @mkdir($subDir, 0755, true);\n            @copy($targetFullPath, $subCand);\n        }\n    }\n\n    // Actualizar registro del producto en MariaDB si se suministró SKU\n    $sku = isset($_GET['sku']) ? trim($_GET['sku']) : (isset($_SERVER['HTTP_X_PRODUCT_SKU']) ? trim($_SERVER['HTTP_X_PRODUCT_SKU']) : null);\n    if ($sku) {\n        $pdo = getDbConnection();\n        if ($pdo) {\n            try {\n                $canonicalImgPath = (strpos($targetRelPath, '/') === 0) ? $targetRelPath : ('/' . $targetRelPath);\n                $updateStmt = $pdo->prepare(\"UPDATE `eb_products` SET `imgart` = :img WHERE `code` = :sku OR `sku` = :sku\");\n                $updateStmt->execute([':img' => $canonicalImgPath, ':sku' => $sku]);\n            } catch (Exception $e) {}\n        }\n    }\n\n    $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';\n    $host = $_SERVER['HTTP_HOST'] ?? 'localhost';\n    $publicUrl = \"{$scheme}://{$host}/assets/img/factusolImg/{$targetRelPath}\";\n\n    echo json_encode([\n        'success' => true,\n        'path' => $targetRelPath,\n        'bytesWritten' => filesize($targetFullPath),\n        'url' => $publicUrl,\n    ]);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: PUSH_CATALOG (Subida masiva de productos desde Bentian Agent)\n// ----------------------------------------------------------------------------\n$pdo = getDbConnection();\nif (!$pdo) {\n    http_response_code(500);\n    echo json_encode(['error' => 'No se pudo conectar a MariaDB']);\n    exit;\n}\nensureTablesExist($pdo);\n\n$rawBody = file_get_contents('php://input');\n$data = json_decode($rawBody, true) ?: [];\n\nif ($mainAction === 'push_catalog' || $mainAction === 'sync_catalog') {\n    $products = isset($data['products']) && is_array($data['products']) ? $data['products'] : [];\n    if (empty($products)) {\n        echo json_encode(['success' => true, 'count' => 0, 'message' => 'No se enviaron productos']);\n        exit;\n    }\n\n    $sql = \"INSERT INTO `eb_products` \n      (`code`, `sku`, `name`, `description`, `section_code`, `section_name`, `family_code`, `family_name`, `price`, `sale_price`, `vat_rate`, `price_with_vat`, `sale_price_with_vat`, `unit_of_measure`, `weight`, `barcode`, `imgart`, `image_url`, `active`, `updated_at`)\n    VALUES \n      (:code, :sku, :name, :description, :section_code, :section_name, :family_code, :family_name, :price, :sale_price, :vat_rate, :price_with_vat, :sale_price_with_vat, :unit_of_measure, :weight, :barcode, :imgart, :image_url, :active, NOW())\n    ON DUPLICATE KEY UPDATE\n      `sku` = VALUES(`sku`),\n      `name` = VALUES(`name`),\n      `description` = VALUES(`description`),\n      `section_code` = VALUES(`section_code`),\n      `section_name` = VALUES(`section_name`),\n      `family_code` = VALUES(`family_code`),\n      `family_name` = VALUES(`family_name`),\n      `price` = VALUES(`price`),\n      `sale_price` = VALUES(`sale_price`),\n      `vat_rate` = VALUES(`vat_rate`),\n      `price_with_vat` = VALUES(`price_with_vat`),\n      `sale_price_with_vat` = VALUES(`sale_price_with_vat`),\n      `unit_of_measure` = VALUES(`unit_of_measure`),\n      `weight` = VALUES(`weight`),\n      `barcode` = VALUES(`barcode`),\n      `imgart` = IF(VALUES(`imgart`) != '', VALUES(`imgart`), `imgart`),\n      `image_url` = IF(VALUES(`image_url`) != '', VALUES(`image_url`), `image_url`),\n      `active` = VALUES(`active`),\n      `updated_at` = NOW()\";\n\n    $stmt = $pdo->prepare($sql);\n    $count = 0;\n\n    $pdo->beginTransaction();\n    try {\n        foreach ($products as $p) {\n            $sku = substr($p['sku'] ?? $p['code'] ?? '', 0, 50);\n            $code = substr($p['code'] ?? $sku, 0, 50);\n            if (empty($code)) continue;\n\n            $regPrice = floatval($p['regularPrice'] ?? $p['price'] ?? 0);\n            $rawSale = isset($p['salePrice']) ? floatval($p['salePrice']) : null;\n            $vat = floatval($p['taxRate'] ?? $p['vat_rate'] ?? 21.0);\n            $withVat = round($regPrice * (1 + $vat / 100), 4);\n            $salePrice = ($rawSale !== null && $rawSale > 0 && $rawSale < $regPrice) ? $rawSale : null;\n            $saleWithVat = $salePrice !== null ? round($salePrice * (1 + $vat / 100), 4) : null;\n\n            // Normalización canónica de imagen con prefijo /\n            $rawImg = '';\n            if (!empty($p['imgart'])) {\n                $rawImg = $p['imgart'];\n            } else if (!empty($p['images']) && is_array($p['images']) && count($p['images']) > 0) {\n                $first = $p['images'][0];\n                $rawImg = is_array($first) ? ($first['src'] ?? '') : strval($first);\n            }\n            $cleanImg = '';\n            if (!empty($rawImg)) {\n                $cleanImg = str_replace('\\\\', '/', $rawImg);\n                if (strpos($cleanImg, '/') !== 0 && !preg_match('#^https?://#i', $cleanImg)) {\n                    $cleanImg = '/' . $cleanImg;\n                }\n            }\n\n            $imgUrl = $p['imageUrl'] ?? $cleanImg;\n\n            $stmt->execute([\n                ':code' => $code,\n                ':sku' => $sku,\n                ':name' => substr($p['name'] ?? '', 0, 255),\n                ':description' => $p['description'] ?? null,\n                ':section_code' => substr($p['section_code'] ?? $p['sectionCode'] ?? '', 0, 10) ?: null,\n                ':section_name' => substr($p['section_name'] ?? $p['sectionName'] ?? '', 0, 100) ?: null,\n                ':family_code' => substr($p['family_code'] ?? $p['familyCode'] ?? '', 0, 10) ?: null,\n                ':family_name' => substr($p['family_name'] ?? $p['familyName'] ?? '', 0, 100) ?: null,\n                ':price' => $regPrice,\n                ':sale_price' => $salePrice,\n                ':vat_rate' => $vat,\n                ':price_with_vat' => $withVat,\n                ':sale_price_with_vat' => $saleWithVat,\n                ':unit_of_measure' => substr($p['unitOfMeasure'] ?? 'UNIDADES', 0, 20),\n                ':weight' => floatval($p['weight'] ?? 0),\n                ':barcode' => substr($p['barcode'] ?? '', 0, 50) ?: null,\n                ':imgart' => $cleanImg ?: null,\n                ':image_url' => $imgUrl ?: null,\n                ':active' => ($p['status'] ?? 'publish') === 'publish' ? 1 : 0,\n            ]);\n            $count++;\n        }\n        $pdo->commit();\n        echo json_encode(['success' => true, 'count' => $count, 'message' => \"Se actualizaron {$count} productos\"]);\n    } catch (Exception $e) {\n        $pdo->rollBack();\n        http_response_code(500);\n        echo json_encode(['error' => 'Fallo al procesar lote de catálogo: ' . $e->getMessage()]);\n    }\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: PUSH_STOCK (Actualización rápida de existencias)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'push_stock') {\n    $updates = isset($data['stockUpdates']) && is_array($data['stockUpdates']) ? $data['stockUpdates'] : [];\n    if (empty($updates)) {\n        echo json_encode(['success' => true, 'count' => 0, 'message' => 'No se enviaron existencias']);\n        exit;\n    }\n\n    $stmt = $pdo->prepare(\"\n        INSERT INTO `eb_stock` (`code`, `stock`, `updated_at`)\n        VALUES (:code, :stock, NOW())\n        ON DUPLICATE KEY UPDATE `stock` = VALUES(`stock`), `updated_at` = NOW()\n    \");\n\n    $count = 0;\n    $pdo->beginTransaction();\n    try {\n        foreach ($updates as $u) {\n            $code = substr($u['code'] ?? $u['sku'] ?? '', 0, 50);\n            if (empty($code)) continue;\n            $stmt->execute([\n                ':code' => $code,\n                ':stock' => floatval($u['stock'] ?? 0),\n            ]);\n            $count++;\n        }\n        $pdo->commit();\n        echo json_encode(['success' => true, 'count' => $count]);\n    } catch (Exception $e) {\n        $pdo->rollBack();\n        http_response_code(500);\n        echo json_encode(['error' => 'Fallo al actualizar existencias: ' . $e->getMessage()]);\n    }\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: PULL_ORDERS (Descarga de pedidos hacia Factusol)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'pull_orders' || $mainAction === 'get_orders') {\n    $limit = isset($_GET['limit']) ? max(1, min(100, intval($_GET['limit']))) : 50;\n    $stmt = $pdo->prepare(\"SELECT * FROM `eb_orders` WHERE `status` = 'PENDING' ORDER BY `id` ASC LIMIT :lim\");\n    $stmt->bindValue(':lim', $limit, PDO::PARAM_INT);\n    $stmt->execute();\n    $rows = $stmt->fetchAll();\n\n    $orders = [];\n    foreach ($rows as $r) {\n        $orders[] = [\n            'id' => intval($r['id']),\n            'order_number' => $r['order_number'],\n            'orderNumber' => $r['order_number'],\n            'status' => $r['status'],\n            'customer' => json_decode($r['customer_data'], true) ?: [],\n            'lines' => json_decode($r['order_lines'], true) ?: [],\n            'payment_method' => $r['payment_method'],\n            'paymentMethod' => $r['payment_method'],\n            'payment_status' => $r['payment_status'] ?? 'COMPLETED',\n            'payment_reference' => $r['payment_reference'] ?? '',\n            'subtotal' => floatval($r['subtotal'] ?? $r['total']),\n            'tax_total' => floatval($r['tax_total'] ?? 0),\n            'shipping_cost' => floatval($r['shipping_cost'] ?? 0),\n            'total' => floatval($r['total']),\n            'created_at' => $r['created_at'],\n            'createdAt' => $r['created_at'],\n        ];\n    }\n    echo json_encode(['success' => true, 'orders' => $orders]);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: ACK_ORDERS (Confirmación de pedidos descargados)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'ack_orders') {\n    $confirmations = isset($data['confirmations']) && is_array($data['confirmations']) ? $data['confirmations'] : [];\n    $stmt = $pdo->prepare(\"\n        UPDATE `eb_orders` \n        SET `status` = 'SYNCED', \n            `factusol_order_number` = :factNum, \n            `factusol_series` = :factSer, \n            `synced_at` = NOW() \n        WHERE `id` = :id\n    \");\n\n    $count = 0;\n    $pdo->beginTransaction();\n    try {\n        foreach ($confirmations as $c) {\n            $stmt->execute([\n                ':id' => intval($c['orderId'] ?? $c['webOrderId'] ?? $c['id'] ?? 0),\n                ':factNum' => intval($c['factusolOrderNumber'] ?? $c['orderNumber'] ?? 0) ?: null,\n                ':factSer' => substr($c['factusolSeries'] ?? '1', 0, 5),\n            ]);\n            $count++;\n        }\n        $pdo->commit();\n        echo json_encode(['success' => true, 'count' => $count]);\n    } catch (Exception $e) {\n        $pdo->rollBack();\n        http_response_code(500);\n        echo json_encode(['error' => 'Fallo al confirmar pedidos']);\n    }\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: PULL_CANCELLED_ORDERS (Descarga de pedidos cancelados para Factusol)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'pull_cancelled_orders' || $mainAction === 'get_cancelled_orders') {\n    $limit = isset($_GET['limit']) ? max(1, min(100, intval($_GET['limit']))) : 50;\n    $stmt = $pdo->prepare(\"\n        SELECT * FROM `eb_orders` \n        WHERE `status` = 'CANCELLED' \n          AND `factusol_order_number` IS NOT NULL \n          AND (`factusol_unstocked` = 0 OR `factusol_unstocked` IS NULL)\n        ORDER BY `id` ASC \n        LIMIT :lim\n    \");\n    $stmt->bindValue(':lim', $limit, PDO::PARAM_INT);\n    $stmt->execute();\n    $rows = $stmt->fetchAll();\n\n    $orders = [];\n    foreach ($rows as $r) {\n        $orders[] = [\n            'id' => intval($r['id']),\n            'order_number' => $r['order_number'],\n            'orderNumber' => $r['order_number'],\n            'status' => $r['status'],\n            'customer' => json_decode($r['customer_data'], true) ?: [],\n            'lines' => json_decode($r['order_lines'], true) ?: [],\n            'payment_method' => $r['payment_method'],\n            'paymentMethod' => $r['payment_method'],\n            'payment_status' => $r['payment_status'] ?? 'CANCELLED',\n            'payment_reference' => $r['payment_reference'] ?? '',\n            'subtotal' => floatval($r['subtotal'] ?? $r['total']),\n            'tax_total' => floatval($r['tax_total'] ?? 0),\n            'shipping_cost' => floatval($r['shipping_cost'] ?? 0),\n            'total' => floatval($r['total']),\n            'factusol_order_number' => intval($r['factusol_order_number']),\n            'factusolOrderNumber' => intval($r['factusol_order_number']),\n            'factusol_series' => $r['factusol_series'] ?? '1',\n            'factusolSeries' => $r['factusol_series'] ?? '1',\n            'created_at' => $r['created_at'],\n            'createdAt' => $r['created_at'],\n        ];\n    }\n    echo json_encode(['success' => true, 'orders' => $orders]);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: ACK_CANCELLED_ORDERS (Confirmación de reposición de stock en Factusol)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'ack_cancelled_orders') {\n    $confirmations = isset($data['confirmations']) && is_array($data['confirmations']) \n        ? $data['confirmations'] \n        : (isset($data['orderIds']) && is_array($data['orderIds']) ? $data['orderIds'] : []);\n\n    $stmt = $pdo->prepare(\"\n        UPDATE `eb_orders` \n        SET `factusol_unstocked` = 1, \n            `unstocked_at` = NOW() \n        WHERE `id` = :id\n    \");\n\n    $count = 0;\n    $pdo->beginTransaction();\n    try {\n        foreach ($confirmations as $c) {\n            $orderId = is_array($c) \n                ? intval($c['orderId'] ?? $c['webOrderId'] ?? $c['id'] ?? 0)\n                : intval($c);\n            if ($orderId > 0) {\n                $stmt->execute([':id' => $orderId]);\n                $count++;\n            }\n        }\n        $pdo->commit();\n        echo json_encode(['success' => true, 'count' => $count]);\n    } catch (Exception $e) {\n        $pdo->rollBack();\n        http_response_code(500);\n        echo json_encode(['error' => 'Fallo al confirmar reposición de pedidos cancelados: ' . $e->getMessage()]);\n    }\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: CLEAN_TEST_DATA (Eliminación de artículos y pedidos de prueba)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'clean_test_data' || $mainAction === 'delete_test_data') {\n    $pdo = getDbConnection();\n    ensureTablesExist($pdo);\n\n    $delProd = $pdo->exec(\"DELETE FROM `eb_products` WHERE `code` = '000001' OR `name` LIKE '%Taladro Percutor%' OR `code` LIKE 'TEST%'\");\n    $delStock = $pdo->exec(\"DELETE FROM `eb_stock` WHERE `code` = '000001' OR `code` LIKE 'TEST%'\");\n    $delOrders = $pdo->exec(\"DELETE FROM `eb_orders` WHERE `order_number` LIKE '%PRUEBA%' OR `order_number` LIKE '%TEST%' OR `customer_data` LIKE '%test@test.com%'\");\n\n    echo json_encode([\n        'success' => true,\n        'deletedProducts' => intval($delProd),\n        'deletedStock' => intval($delStock),\n        'deletedOrders' => intval($delOrders),\n        'message' => 'Datos de prueba eliminados correctamente de la base de datos de la tienda online',\n    ]);\n    exit;\n}\n\n// ----------------------------------------------------------------------------\n// ACCIÓN PROTEGIDA: DELETE_PRODUCT (Eliminación de artículo individual por código)\n// ----------------------------------------------------------------------------\nif ($mainAction === 'delete_product' || $mainAction === 'delete_article') {\n    $code = trim($_GET['code'] ?? $data['code'] ?? $data['codart'] ?? '');\n    if (empty($code)) {\n        http_response_code(400);\n        echo json_encode(['error' => 'Código de artículo no especificado (parámetro code)']);\n        exit;\n    }\n    $pdo = getDbConnection();\n    ensureTablesExist($pdo);\n    $stmt1 = $pdo->prepare(\"DELETE FROM `eb_products` WHERE `code` = :code\");\n    $stmt1->execute([':code' => $code]);\n    $stmt2 = $pdo->prepare(\"DELETE FROM `eb_stock` WHERE `code` = :code\");\n    $stmt2->execute([':code' => $code]);\n    echo json_encode([\n        'success' => true,\n        'code' => $code,\n        'message' => \"Artículo {$code} eliminado correctamente de la tienda web\",\n    ]);\n    exit;\n}\n\nhttp_response_code(400);\necho json_encode(['error' => 'Acción no válida: ' . htmlspecialchars($mainAction)]);\n";
